@RabbitListener(queues = "order-processing-queue")
public void handleOrder(OrderEvent event) {
    try {
        orderService.process(event);
    } catch (Exception e) {
        // Log error, RabbitMQ will requeue or move to DLX based on config
        throw new AmqpRejectAndDontRequeueException("Fatal processing error");
    }
}
